content:
Problem Description:
Consider a finite state machine that is used to control some type of motor. The FSM has inputs x and y, which come from the motor, and produces outputs f and g, which control the motor. There is also a clock input called clk and a reset input (synchronous, active low) called resetn. The FSM has to work as follows. As long as the reset input is asserted, the FSM stays in a beginning state, called state A. When the reset signal is de-asserted, then after the next clock edge the FSM has to set the output f to 1 for one clock cycle. Then, the FSM has to monitor the x input. When x has produced the values 1, 0, 1 in three successive clock cycles, then g should be set to 1 on the following clock cycle. While maintaining g = 1 the FSM has to monitor the y input. If y has the value 1 within at most two clock cycles, then the FSM should maintain g = 1 permanently (that is, until reset). But if y does not become 1 within two clock cycles, then the FSM should set g = 0 permanently (until reset).

module top_module (
	input clk,
	input resetn,
	input x,
	input y,
	output f,
	output g
);

Erroneous Implementation:

f is assigned to 1 when the state is B.
g is assigned to 1 when the state is G1 or G2 or P1.
module top_module (
input clk,
input resetn,
input x,
input y,
output reg f,
output reg g
);
parameter A = 0;
parameter B = 1;
parameter S0 = 2;
parameter S1 = 3;
parameter S10 = 4;
parameter G1 = 5;
parameter G2 = 6;
parameter P0 = 7;
parameter P1 = 8;
reg [3:0] state;
reg [3:0] next_state;
always @(posedge clk or negedge resetn) begin
if (!resetn) begin
state <= A;
end else begin
state <= next_state;
end
end
always @(state, x, y) begin
case (state)
A: begin
if (x) begin
next_state = B;
end else begin
next_state = S0;
end
end
B: begin
next_state = S0;
end
S0: begin
if (x) begin
next_state = S1;
end else begin
next_state = S0;
end
end
S1: begin
if (x) begin
next_state = S1;
end else begin
next_state = S10;
end
end
S10: begin
if (x) begin
next_state = G1;
end else begin
next_state = S0;
end
end
G1: begin
if (y) begin
next_state = P1;
end else begin
next_state = G2;
end
end
G2: begin
if (y) begin
next_state = P1;
end else begin
next_state = P0;
end
end
P0: begin
next_state = P0;
end
P1: begin
next_state = P1;
end
endcase
end
always @(state) begin
case (state)
B: begin
f = 1;
end
G1, G2, P1: begin
g = 1;
end
default: begin
f = 0;
g = 0;
end
endcase
end
endmodule

